-- A person on a sheet: a name and a grade (A, B or C). Listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person's aliases: other names they go by, each kept with surrounding spaces removed and with
-- its key (ignoring case). An alias shares the names' uniqueness on the sheet: no alias equals,
-- by key, any name or other alias there.
CREATE TABLE person_alias (
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) NOT NULL,
    PRIMARY KEY (person_id, alias_key)
);
-- A person who arrives on a sheet by transfer and is merged into someone there joins their aliases to
-- that person's, so one person may hold aliases that differ only in case: an alias is now kept once
-- per person as it is written, rather than once per key.
ALTER TABLE person_alias DROP PRIMARY KEY;
ALTER TABLE person_alias ADD PRIMARY KEY (person_id, alias);
package net.officefloor.hq.app.person;

import java.util.Collection;
